          actorType: "seller",
          requestedGrade: "super_admin",
          createdAtFrom: thirtyDaysAgo.toISOString(),
          createdAtTo: now.toISOString(),
        } satisfies IEcommerceMallAdminRequestOfCustomer.IRequest,
      },
    );
