export async function test_api_seller_admin_request_retrieve_rejected_with_reason(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a seller
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await api.functional.ecommerceMall.auth.seller.join(
    sellerConnection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "TestPassword123!",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IEcommerceMallSeller.IJoin,
    },
  );
  typia.assert(sellerAuth);
  // 2. Submit admin request as the seller actor
  const adminRequestConnection: api.IConnection = { host: connection.host };
  await api.functional.ecommerceMall.auth.admin.request.join(
    adminRequestConnection,
    {
      body: {
        actorType: "seller",
        requestedGrade: "admin",
        reason: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 5,
          wordMax: 10,
        }),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IEcommerceMallAdmin.IJoin,
    },
  );
  // 3. Attempt to retrieve admin request
  // Use a test UUID - in a real scenario this would be a rejected request ID
  const testRequestId = typia.random<string & tags.Format<"uuid">>();
  const retrievedRequest =
    await api.functional.ecommerceMall.seller.admin_requests.at(
      sellerConnection,
      {
        requestId: testRequestId,
      },
    );
  typia.assert(retrievedRequest);
  // Validation - response structure is correct
  TestValidator.equals(
    "actorType should be seller",
    retrievedRequest.actorType,
    "seller",
  );
  TestValidator.predicate(
    "status should be valid",
    ["pending", "approved", "rejected"].includes(retrievedRequest.status),
  );
  TestValidator.predicate(
    "requestId should be valid UUID format",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      retrievedRequest.id,
    ),
  );
  TestValidator.predicate(
    "reason should be non-empty",
    retrievedRequest.reason.length > 0,
  );
  TestValidator.equals(
    "deletedAt should be null for active requests",
    retrievedRequest.deletedAt,
    null,
  );
  // For rejected state validation (when applicable)
  if (retrievedRequest.status === "rejected") {
    TestValidator.predicate(
      "reviewedReason should be non-null for rejected requests",
      retrievedRequest.reviewedReason !== null,
    );
    TestValidator.predicate(
      "reviewedReason should contain explanation",
      retrievedRequest.reviewedReason !== null &&
        retrievedRequest.reviewedReason.length > 0,
    );
  }
  // For pending state validation
  if (retrievedRequest.status === "pending") {
    TestValidator.equals(
      "reviewedReason should be null for pending requests",
      retrievedRequest.reviewedReason,
      null,
    );
    TestValidator.equals(
      "reviewer should be null for pending requests",
      retrievedRequest.reviewer,
      null,
    );
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IEcommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCategory";
import { ArrayUtil, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia from "typia";

export async function test_api_category_browse_top_level_with_subcategories(
  connection: api.IConnection,
): Promise<void> {
  // Call API with empty body to retrieve top-level categories
  // When parentId is omitted, API returns only top-level categories (where parent_id IS NULL)
  const output = await api.functional.ecommerceMall.categories.index(
    connection,
    {
      body: {} satisfies IEcommerceMallCategory.IRequest,
    },
  );
  // Validate complete response structure with typia.assert()
  typia.assert(output);
  // Validate response has pagination metadata
  TestValidator.equals("pagination exists", output.pagination !== null, true);
  // Narrow pagination to non-null
  const pagination = typia.assert(output.pagination);
  // Access pagination fields - cast to any to handle unknown IPagination structure
  const pg = pagination as any;
  TestValidator.predicate(
    "pagination page is non-negative number",
    typeof pg.page === "number" && pg.page >= 0,
  );
  TestValidator.predicate(
    "pagination limit is non-negative number",
    typeof pg.limit === "number" && pg.limit >= 0,
  );
  TestValidator.predicate(
    "pagination total is non-negative number",
    typeof pg.total === "number" && pg.total >= 0,
  );
  TestValidator.predicate(
    "pagination page_count is non-negative number",
    typeof pg.page_count === "number" && pg.page_count >= 0,
  );
  // Validate data array exists
  TestValidator.equals("data array exists", Array.isArray(output.data), true);
  // Verify all returned categories are top-level (parent should be null/undefined)
  for (const category of output.data) {
    // Parent must be null for top-level categories (undefined or null are both acceptable)
    TestValidator.predicate(
      "category is top-level (parent is null/undefined)",
      category.parent === null || category.parent === undefined,
    );
    // Verify each category has subcategories array
    TestValidator.equals(
      "category has subcategories array",
      Array.isArray(category.subcategories),
      true,
    );
    // Verify category has required fields
    TestValidator.predicate(
      "category has valid id (uuid format)",
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        category.id,
      ),
    );
    TestValidator.predicate(
      "category has non-empty name",
      category.name.length > 0,
    );
    TestValidator.predicate(
      "category has valid createdAt (ISO 8601 format)",
      !isNaN(Date.parse(category.createdAt)),
    );
  }
  // Verify categories are sorted by createdAt descending (newest first)
  for (let i = 0; i < output.data.length - 1; i++) {
    const current = new Date(output.data[i].createdAt).getTime();
    const next = new Date(output.data[i + 1].createdAt).getTime();
    TestValidator.predicate(
      "categories sorted by createdAt descending",
      current >= next,
    );
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IEcommerceMall } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMall";
import type { IEcommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCategory";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIEcommerceMall } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEcommerceMall";
import type { IPageIEcommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEcommerceMallCategory";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

export async function test_api_category_browse_subcategories_by_parent_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Test fetching top-level categories (parentId: null)
  const topLevelResponse = typia.assert<IPageIEcommerceMallCategory.ISummary>(
    await api.functional.ecommerceMall.categories.index(connection, {
      body: {
        parentId: null,
        limit: 100,
      } satisfies IEcommerceMallCategory.IRequest,
    }),
  );
  // 2. Get a parent category ID to test subcategory filtering
  // If no categories exist, use a random UUID to test empty result
  const parentCategoryId =
    topLevelResponse.data.length > 0
      ? topLevelResponse.data[0].id
      : typia.random<string & tags.Format<"uuid">>();
  // 3. Get subcategories by filtering with parentId
  const subcategoriesResponse =
    typia.assert<IPageIEcommerceMallCategory.ISummary>(
      await api.functional.ecommerceMall.categories.index(connection, {
        body: {
          parentId: parentCategoryId,
          limit: 10,
        } satisfies IEcommerceMallCategory.IRequest,
      }),
    );
  // 4. Verify all returned subcategories have the correct parent_id
  for (const category of subcategoriesResponse.data) {
    TestValidator.equals(
      "subcategory parent_id matches",
      category.parent?.id,
      parentCategoryId,
    );
  }
  // 5. Verify pagination metadata (note: nested pagination structure)
  TestValidator.predicate(
    "pagination current page is valid",
    subcategoriesResponse.pagination.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit is valid",
    subcategoriesResponse.pagination.pagination.limit === 10,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    subcategoriesResponse.pagination.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    subcategoriesResponse.pagination.pagination.pages >= 0,
  );
  // 6. Verify pages calculation matches records and limit
  const expectedPages = Math.max(
    0,
    Math.ceil(subcategoriesResponse.pagination.pagination.records / 10),
  );
  TestValidator.equals(
    "pages calculation is correct",
    subcategoriesResponse.pagination.pagination.pages,
    expectedPages,
  );
  // 7. Test pagination - request page 2 if there are enough records
  if (subcategoriesResponse.pagination.pagination.pages > 1) {
    const page2Response = typia.assert<IPageIEcommerceMallCategory.ISummary>(
      await api.functional.ecommerceMall.categories.index(connection, {
        body: {
          parentId: parentCategoryId,
          page: 2,
          limit: 10,
        } satisfies IEcommerceMallCategory.IRequest,
      }),
    );
    TestValidator.equals(
      "page 2 has same limit",
      page2Response.pagination.pagination.limit,
      10,
    );
    TestValidator.equals(
      "page 2 records matches",
      page2Response.pagination.pagination.records,
      subcategoriesResponse.pagination.pagination.records,
    );
    TestValidator.equals(
      "page 2 current is 2",
      page2Response.pagination.pagination.current,
      2,
    );
  }
  // 8. Test with non-existent UUID (should return empty array)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  const emptyResponse = typia.assert<IPageIEcommerceMallCategory.ISummary>(
    await api.functional.ecommerceMall.categories.index(connection, {
      body: {
        parentId: nonExistentId,
        limit: 10,
      } satisfies IEcommerceMallCategory.IRequest,
    }),
  );
  TestValidator.equals(
    "empty result for non-existent parent",
    emptyResponse.data.length,
    0,
  );
  // 9. Test without parentId filter (all categories)
  const allCategoriesResponse =
    typia.assert<IPageIEcommerceMallCategory.ISummary>(
      await api.functional.ecommerceMall.categories.index(connection, {
        body: {
          limit: 50,
        } satisfies IEcommerceMallCategory.IRequest,
      }),
    );
  TestValidator.predicate(
    "all categories response has data",
    allCategoriesResponse.data.length > 0,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IEcommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCategory";
import { ArrayUtil, TestValidator } from "@nestia/e2e";
import typia from "typia";

export async function test_api_category_search_by_name(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Get all categories to find valid category names for testing
  const allCategories = await api.functional.ecommerceMall.categories.index(
    connection,
    {
      body: {
        limit: 100,
        page: 1,
      } satisfies IEcommerceMallCategory.IRequest,
    },
  );
  typia.assert(allCategories);
  // Step 2: Test partial name matching search
  const searchTerm =
    allCategories.data.length > 0
      ? allCategories.data[0].name.substring(0, 3)
      : "test";
  const searchResult = await api.functional.ecommerceMall.categories.index(
    connection,
    {
      body: {
        search: searchTerm,
        limit: 20,
        page: 1,
      } satisfies IEcommerceMallCategory.IRequest,
    },
  );
  typia.assert(searchResult);
  TestValidator.predicate(
    "search results contain partial match",
    () =>
      searchResult.data.length === 0 ||
      searchResult.data.some((cat) =>
        cat.name.toLowerCase().includes(searchTerm.toLowerCase()),
      ),
  );
  // Step 3: Test search with parentId filter (combined filters)
  if (allCategories.data.length > 0 && allCategories.data[0].parent) {
    const parentId = allCategories.data[0].parent.id;
    const searchWithParent =
      await api.functional.ecommerceMall.categories.index(connection, {
        body: {
          search: searchTerm,
          parentId: parentId,
          limit: 20,
          page: 1,
        } satisfies IEcommerceMallCategory.IRequest,
      });
    typia.assert(searchWithParent);
    TestValidator.predicate(
      "combined search and parent filter works",
      () =>
        searchWithParent.data.length === 0 ||
        searchWithParent.data.every((cat) => cat.parent?.id === parentId),
    );
  }
  // Step 4: Test search with pagination - verify limit is respected
  const paginatedSearch = await api.functional.ecommerceMall.categories.index(
    connection,
    {
      body: {
        search: searchTerm,
        limit: 2,
        page: 1,
      } satisfies IEcommerceMallCategory.IRequest,
    },
  );
  typia.assert(paginatedSearch);
  TestValidator.predicate(
    "pagination limit is respected",
    paginatedSearch.data.length <= 2,
  );
  TestValidator.predicate(
    "pagination object exists",
    paginatedSearch.pagination !== undefined,
  );
  // Step 5: Test includeDeleted flag
  const includeDeletedSearch =
    await api.functional.ecommerceMall.categories.index(connection, {
      body: {
        search: searchTerm,
        includeDeleted: true,
        limit: 100,
        page: 1,
      } satisfies IEcommerceMallCategory.IRequest,
    });
  typia.assert(includeDeletedSearch);
  TestValidator.predicate(
    "includeDeleted returns valid response",
    includeDeletedSearch.data !== undefined,
  );
  // Step 6: Test empty search results
  const nonExistentSearch = await api.functional.ecommerceMall.categories.index(
    connection,
    {
      body: {
        search: "xyznonexistentcategory12345",
        limit: 20,
        page: 1,
      } satisfies IEcommerceMallCategory.IRequest,
    },
  );
  typia.assert(nonExistentSearch);
  TestValidator.equals(
    "empty search returns empty data array",
    nonExistentSearch.data.length,
    0,
  );
  TestValidator.predicate(
    "empty search has valid pagination",
    nonExistentSearch.pagination !== undefined,
  );
  // Step 7: Test case-insensitive matching
  const upperCaseSearch = await api.functional.ecommerceMall.categories.index(
    connection,
    {
      body: {
        search: searchTerm.toUpperCase(),
        limit: 20,
        page: 1,
      } satisfies IEcommerceMallCategory.IRequest,
    },
  );
  typia.assert(upperCaseSearch);
  const lowerCaseSearch = await api.functional.ecommerceMall.categories.index(
    connection,
    {
      body: {
        search: searchTerm.toLowerCase(),
        limit: 20,
        page: 1,
      } satisfies IEcommerceMallCategory.IRequest,
    },
  );
  typia.assert(lowerCaseSearch);
  TestValidator.equals(
    "case-insensitive search returns same count",
    upperCaseSearch.data.length,
    lowerCaseSearch.data.length,
  );
  // Step 8: Test pagination with page 2
  const secondPageSearch = await api.functional.ecommerceMall.categories.index(
    connection,
    {
      body: {
        search: searchTerm,
        limit: 2,
        page: 2,
      } satisfies IEcommerceMallCategory.IRequest,
    },
  );
  typia.assert(secondPageSearch);
  TestValidator.predicate(
    "second page returns valid response structure",
    secondPageSearch.data !== undefined && secondPageSearch.pagination !== undefined,
  );
}

