  // 2. Seller A registers and authenticates
  const sellerAConnection: api.IConnection = { host: connection.host };
  const sellerAReg = await authorize_seller_join(sellerAConnection, {});
  typia.assert(sellerAReg);
  const sellerALoginConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerALoginConnection, {
    body: {
      email: sellerAReg.email,
      password: RandomGenerator.alphaNumeric(16),
    },
  });
  // 3. Seller B registers and authenticates
  const sellerBConnection: api.IConnection = { host: connection.host };
  const sellerBReg = await authorize_seller_join(sellerBConnection, {});
  typia.assert(sellerBReg);
  const sellerBLoginConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerBLoginConnection, {
    body: {
      email: sellerBReg.email,
      password: RandomGenerator.alphaNumeric(16),
    },
  });
  // 4. Seller A creates a product with the category
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerALoginConnection,
    {
      body: {
        categoryId: category.id,
