  // 6. Seller A adds an option value to their variant
  const optionValue =
    await generate_random_ecommerce_mall_seller_products_variants_option_values_create(
      sellerALoginConnection,
      {
        params: {
          productId: product.id,
          variantId: variant.id,
        },
      },
    );
  typia.assert(optionValue);
  // 7. Seller B attempts to update Seller A's option value via PUT request
  // 8. Verify 403 Forbidden response is returned
  // 9. Verify error message indicates unauthorized access to resource
  await TestValidator.httpError(
    "Seller B cannot update Seller A's option value",
    403,
    async () =>
      await api.functional.ecommerceMall.seller.products.variants.option_values.putByProductidAndVariantidAndOptionvalueid(
        sellerBLoginConnection,
        {
          productId: product.id,
          variantId: variant.id,
          optionValueId: optionValue.id,
          body: {
            value: "Updated Value",
          },
        },
      ),
  );
