export async function test_api_inventory_records_date_range_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as admin
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Create seller for product ownership
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 3. Create category (required for product)
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    {},
  );
  // 4. Create product
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  // 5. Create variant
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
        },
      },
    );
  // 6. Create multiple inventory records with different reasons
  const startDate = new Date();
  startDate.setHours(startDate.getHours() - 1);
  // Create restock record (should be included in filter)
  await generate_random_ecommerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      params: {
        productId: product.id,
        variantId: variant.id,
      },
      body: {
        operationType: "restock",
        quantity: 100,
        reason: "restock",
      },
    },
  );
  // Create order_placement record (should be excluded from filter)
  await generate_random_ecommerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      params: {
        productId: product.id,
        variantId: variant.id,
      },
      body: {
        operationType: "adjustment",
        quantity: 10,
        reason: "order_placement",
      },
    },
  );
  // Create adjustment record (should be excluded from filter)
  await generate_random_ecommerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      params: {
        productId: product.id,
        variantId: variant.id,
      },
      body: {
        operationType: "adjustment",
        quantity: 5,
        reason: "adjustment",
      },
    },
  );
  const endDate = new Date();
  // 7. Query filtered inventory records with date range and reason filter
