  TestValidator.predicate(
    "has valid overview structure",
    retrievedOverview.totalVariantsCount >= 0,
  );
  TestValidator.predicate(
    "has valid total stock quantity",
    retrievedOverview.totalStockQuantity >= 0,
  );
  TestValidator.predicate(
    "has valid stock counts",
    retrievedOverview.totalStockQuantity >= 0 &&
      retrievedOverview.inStockCount >= 0 &&
      retrievedOverview.outOfStockCount >= 0,
  );
  TestValidator.predicate(
    "has recent changes array",
    retrievedOverview.recentChanges !== null &&
      retrievedOverview.recentChanges !== undefined,
  );
  TestValidator.predicate(
    "recent changes has at least one entry",
    retrievedOverview.recentChanges.length > 0,
  );
  const createdRecordInRecentChanges = retrievedOverview.recentChanges.find(
    (change) =>
      change.variantSku === variant.skuCode &&
      change.productName === product.name,
  );
  TestValidator.predicate(
    "created record appears in recentChanges",
    createdRecordInRecentChanges !== null &&
      createdRecordInRecentChanges !== undefined,
  );
  if (createdRecordInRecentChanges) {
    TestValidator.equals(
      "quantity change matches",
      createdRecordInRecentChanges.quantityChange,
      restockQuantity,
    );
    TestValidator.equals(
      "reason matches",
      createdRecordInRecentChanges.reason,
      restockReason,
    );
    TestValidator.predicate(
      "has valid createdAt timestamp",
      createdRecordInRecentChanges.createdAt !== null &&
        createdRecordInRecentChanges.createdAt !== undefined,
    );
    TestValidator.equals(
      "variant SKU matches",
      createdRecordInRecentChanges.variantSku,
      variant.skuCode,
    );
    TestValidator.equals(
      "product name matches",
      createdRecordInRecentChanges.productName,
      product.name,
    );
  }
}

