export async function test_api_inventory_record_access_denied_for_other_seller(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin creates a category (required for product creation)
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_login(adminConnection, {
    body: {
      email: "admin@test.com",
      password: "1234",
      href: "http://localhost",
      referrer: "http://localhost",
    } satisfies IEcommerceMallAdmin.ILogin,
  });
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    {},
  );
  // 2. Seller A creates product, variant, and inventory record
  const sellerACredentials = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
  };
  const sellerAJoinConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerAJoinConnection, {
    body: {
      email: sellerACredentials.email,
      password: sellerACredentials.password,
      href: "http://localhost",
      referrer: "http://localhost",
    } satisfies IEcommerceMallSeller.IJoin,
  });
  const sellerAConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerAConnection, {
    body: {
      email: sellerACredentials.email,
      password: sellerACredentials.password,
    } satisfies IEcommerceMallSeller.ILogin,
  });
  // Seller A creates a product
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerAConnection,
    {
      body: {
        categoryId: category.id,
        name: RandomGenerator.paragraph({ sentences: 1 }),
        description: RandomGenerator.paragraph({ sentences: 2 }),
        basePrice: 10000,
      },
    },
  );
  // Seller A creates a variant
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerAConnection,
      {
        params: { productId: product.id },
        body: {
          skuCode: RandomGenerator.alphaNumeric(10),
          quantity: 0,
        },
      },
    );
  // Seller A creates an inventory record (overview response, no ID available)
  await generate_random_ecommerce_mall_seller_product_variants_inventory_records_create(
    sellerAConnection,
    {
      params: { variantId: variant.id },
      body: {
        quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
        operationType: "restock",
        reason: "initial stock",
      },
    },
  );
  // 3. Seller B registers and authenticates (different seller)
  const sellerBCredentials = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
  };
  const sellerBJoinConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerBJoinConnection, {
    body: {
      email: sellerBCredentials.email,
      password: sellerBCredentials.password,
      href: "http://localhost",
      referrer: "http://localhost",
    } satisfies IEcommerceMallSeller.IJoin,
  });
  const sellerBConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerBConnection, {
    body: {
      email: sellerBCredentials.email,
      password: sellerBCredentials.password,
    } satisfies IEcommerceMallSeller.ILogin,
  });
  // 4. Seller B attempts to access Seller A's variant's inventory records
  // Expected: 403 Forbidden - permission denied (Seller B doesn't own the variant)
  // Note: Using a random UUID since the create response doesn't include inventory record IDs
  const fakeInventoryRecordId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError(
    "Seller B cannot access Seller A's variant inventory records",
    403,
    async () =>
      await api.functional.ecommerceMall.seller.productVariants.inventoryRecords.at(
        sellerBConnection,
        {
          variantId: variant.id,
          inventoryRecordId: fakeInventoryRecordId,
        },
      ),
  );
}

