          carrier: "DHL",
          trackingNumber: "1234567890",
        },
      },
    );
  typia.assert(shipment);
  // Verify shipment items exist
  TestValidator.equals(
    "shipment should have items",
    shipment.shipmentItems.length > 0,
    true,
  );
