export async function test_api_refund_rejection_with_reason(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and approve seller
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 2. Create product with variant and inventory
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {},
    },
  );
  // Get variant ID from product
  const variantId = product.variants[0]!.id;
  const productId = product.id;
  // Add inventory to the variant
  await generate_random_ecommerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      params: { productId, variantId },
      body: {
        operationType: "restock",
        quantity: 100,
        reason: "Initial stock",
      },
    },
  );
  // 3. Register customer and create shipping address
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const address =
    await generate_random_ecommerce_mall_customer_customers_addresses_create(
      customerConnection,
      {
        body: {},
      },
    );
  // 4. Customer adds item to cart
  await generate_random_ecommerce_mall_customer_customers_cart_items_create(
    customerConnection,
    {
      body: { productVariantId: variantId, quantity: 1 },
    },
  );
  // 5. Customer checks out
  const order = await generate_random_ecommerce_mall_customer_payments_checkout(
    customerConnection,
    {
      body: { shippingAddressId: address.id },
    },
  );
  typia.assert(order);
  // 6. Seller ships items
  const orderItemId = order.orderItems[0]!.id;
  await generate_random_ecommerce_mall_seller_orders_shipments_create(
    sellerConnection,
    {
      params: { orderId: order.id },
      body: {
        orderItemIds: [orderItemId],
        carrier: "DHL",
        trackingNumber: "1234567890",
      },
    },
  );
  // 7. Customer confirms delivery (get order to see updated status)
  const orderDetail =
    await api.functional.ecommerceMall.customer.ecommerceMall.orders.at(
      customerConnection,
      {
        orderId: order.id,
      },
    );
  typia.assert(orderDetail);
  // 8. Customer submits refund request
  const refundRequest =
    await generate_random_ecommerce_mall_customer_refund_requests_create(
      customerConnection,
      {
        body: {
          orderItemId,
          sellerId: product.seller.seller.id,
          reason: "Product not as described",
        },
      },
    );
  typia.assert(refundRequest);
  // 9. Seller rejects refund with reason
  // Note: The IUpdate type only contains sellerResponse field
  // The rejection reason is captured by the server
  const updatedRefundRequest =
    await api.functional.ecommerceMall.seller.refund_requests.update(
      sellerConnection,
      {
        requestId: refundRequest.id,
        body: {
          sellerResponse: "rejected",
        } satisfies IEcommerceMallRefundRequest.IUpdate,
      },
    );
  typia.assert(updatedRefundRequest);
  // Validate response
  TestValidator.equals(
    "status is rejected",
    updatedRefundRequest.snapshotStatus,
    "rejected",
  );
  TestValidator.equals(
    "seller response is rejected",
    updatedRefundRequest.sellerResponse,
    "rejected",
  );
  // Verify order item remains in delivered status
  const finalOrder =
    await api.functional.ecommerceMall.customer.ecommerceMall.orders.at(
      customerConnection,
      {
        orderId: order.id,
      },
    );
  typia.assert(finalOrder);
  const orderItem = finalOrder.orderItems.find(
    (item) => item.id === orderItemId,
  );
  if (orderItem) {
    TestValidator.equals(
      "order item remains delivered",
      orderItem.status,
      "delivered",
    );
  }
}

