export async function test_api_admin_request_listing_by_super_admin(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create super admin account
  const superAdminConnection: api.IConnection = { host: connection.host };
  await authorize_super_admin_join(superAdminConnection, {});
  // 2. Create customer account
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 3. Create seller account
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 4. Customer submits admin request
  const customerAdminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(customerAdminConnection, {
    body: {
      actorType: "customer",
      requestedGrade: "admin",
      reason: "I want to help manage the platform as a customer user",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceMallAdmin.IJoin,
  });
  // 5. Seller submits admin request
  const sellerAdminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(sellerAdminConnection, {
    body: {
      actorType: "seller",
      requestedGrade: "admin",
      reason: "I need admin access to better manage my shop operations",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceMallAdmin.IJoin,
  });
  // 6. Super admin retrieves all admin requests
  const response =
    await api.functional.ecommerceMall.admin.admin.requests.index(
      superAdminConnection,
      {
        body: {} satisfies IEcommerceMallAdminRequestOfCustomer.IRequest,
      },
    );
  typia.assert(response);
  // 7. Validate pagination metadata
  TestValidator.predicate(
    "has pagination metadata",
    response.pagination !== null && response.pagination !== undefined,
  );
  const pagination = response.pagination as Record<string, any>;
  TestValidator.predicate(
    "pagination has current page",
    pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination has limit",
    pagination.limit > 0,
  );
  TestValidator.predicate(
    "pagination has records count",
    pagination.records >= 2,
  );
  TestValidator.predicate(
    "pagination has pages count",
    pagination.pages >= 1,
  );
  // 8. Validate at least 2 requests exist (customer + seller)
  TestValidator.predicate("has at least 2 requests", response.data.length >= 2);
  // 9. Validate each request has required fields and is typed correctly
  for (const request of response.data) {
    typia.assert(request);
    TestValidator.predicate(
      "actorType is valid",
      request.actorType === "customer" || request.actorType === "seller",
    );
    TestValidator.equals(
      "requestedGrade is valid",
      request.requestedGrade === "admin" ||
        request.requestedGrade === "super_admin",
      true,
    );
    TestValidator.equals("status is pending", request.status, "pending");
  }
  // 10. Validate actor information is populated correctly
  const customerRequest = response.data.find((r) => r.actorType === "customer");
  const sellerRequest = response.data.find((r) => r.actorType === "seller");
  TestValidator.predicate(
    "customer request exists",
    customerRequest !== undefined,
  );
  TestValidator.predicate("seller request exists", sellerRequest !== undefined);
  if (customerRequest?.actor) {
    TestValidator.predicate(
      "customer request has customer actor",
      "email" in customerRequest.actor,
    );
  }
  if (sellerRequest?.actor) {
    TestValidator.predicate(
      "seller request has seller actor",
      "email" in sellerRequest.actor,
    );
  }
  // 11. Validate sorting is by created_at descending (newest first)
  for (let i = 1; i < response.data.length; i++) {
    const prev = new Date(response.data[i - 1].createdAt).getTime();
    const curr = new Date(response.data[i].createdAt).getTime();
    TestValidator.predicate(
      "requests sorted by createdAt descending",
      prev >= curr,
    );
  }
}

