    current: number;
    limit: number;
    records: number;
    pages: number;
  };
  TestValidator.predicate(
    "pagination has current page",
    pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination has limit",
    pagination.limit > 0,
  );
  TestValidator.predicate(
    "pagination has records",
    pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination has pages",
    pagination.pages >= 0,
  );
  // 7. Validate data structure
  TestValidator.equals(
