export async function test_api_inventory_history_filtering_by_reason(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as seller
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  sellerConnection.headers = {
    Authorization: `Bearer ${seller.token.access}`,
  };
  // 2. Create a product
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  // 3. Create a product variant
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  // 4. Create inventory records with different reasons
  // Create restock records
  await generate_random_ecommerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      body: {
        quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
        operationType: "restock",
        reason: "restock",
      },
      params: { productId: product.id, variantId: variant.id },
    },
  );
  await generate_random_ecommerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      body: {
        quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
        operationType: "restock",
        reason: "restock_from_supplier",
      },
      params: { productId: product.id, variantId: variant.id },
    },
  );
  // Create adjustment records
  await generate_random_ecommerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      body: {
        quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
        operationType: "adjustment",
        reason: "adjustment",
      },
      params: { productId: product.id, variantId: variant.id },
    },
  );
  await generate_random_ecommerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      body: {
        quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
        operationType: "adjustment",
        reason: "damaged_goods",
      },
      params: { productId: product.id, variantId: variant.id },
    },
  );
  // 5. Call PATCH /ecommerceMall/seller/variants/{variantId}/inventory with reason filter 'restock'
  const restockFilterResponse =
    await api.functional.ecommerceMall.seller.variants.inventory.index(
      sellerConnection,
      {
        variantId: variant.id,
        body: {
          reason: "restock",
        } satisfies IEcommerceMallInventoryRecord.IRequest,
      },
    );
  typia.assert(restockFilterResponse);
  // 6. Verify only restock records are returned
  TestValidator.equals(
    "restock filter returns correct count",
    restockFilterResponse.data.length,
    2,
  );
  for (const record of restockFilterResponse.data) {
    TestValidator.predicate(
      "record reason contains 'restock'",
      record.reason.includes("restock"),
    );
  }
  // 7. Call with reason filter set to 'adjustment'
  const adjustmentFilterResponse =
    await api.functional.ecommerceMall.seller.variants.inventory.index(
      sellerConnection,
      {
        variantId: variant.id,
        body: {
          reason: "adjustment",
        } satisfies IEcommerceMallInventoryRecord.IRequest,
      },
    );
  typia.assert(adjustmentFilterResponse);
  // 8. Verify only adjustment records are returned
  TestValidator.equals(
    "adjustment filter returns correct count",
    adjustmentFilterResponse.data.length,
    2,
  );
  for (const record of adjustmentFilterResponse.data) {
    TestValidator.predicate(
      "record reason contains 'adjustment'",
      record.reason.includes("adjustment"),
    );
  }
}

