export async function test_api_checkout_blocked_with_deleted_variant(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer joins and authenticates
  const customerAuthorized = await authorize_customer_join(connection, {});
  const customerConnection: api.IConnection = { host: connection.host };
  customerConnection.headers = {
    Authorization: `Bearer ${customerAuthorized.token.access}`,
  };
  // 2. Customer creates shipping address
  const address =
    await generate_random_ecommerce_mall_customer_customers_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 3. Seller joins and authenticates
  const sellerAuthorized = await authorize_seller_join(connection, {});
  const sellerConnection: api.IConnection = { host: connection.host };
  sellerConnection.headers = {
    Authorization: `Bearer ${sellerAuthorized.token.access}`,
  };
  // 4. Seller creates product (skip if not approved)
  if (sellerAuthorized.approvalStatus !== "approved") {
    console.log("Seller not approved, skipping test");
    return;
  }
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 5. Seller creates variant
  const quantity = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<0>
  >();
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: { skuCode: RandomGenerator.alphaNumeric(10), quantity },
      },
    );
  typia.assert(variant);
  // 6. Customer adds variant to cart
  const cartQuantity = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();
  const cartItem =
    await api.functional.ecommerceMall.customer.ecommerceMall.cart.items.create(
      customerConnection,
      {
        body: {
          variantId: variant.id,
          quantity: cartQuantity,
        } satisfies IEcommerceMallCartItem.IRequest,
      },
    );
  typia.assert(cartItem);
  // 7. Seller deletes variant
  await api.functional.ecommerceMall.seller.products.variants.erase(
    sellerConnection,
    {
      productId: product.id,
      variantId: variant.id,
    },
  );
  // 8. Customer attempts checkout - should be blocked
  await TestValidator.error(
    "checkout blocked with unavailable items",
    async () => {
      await api.functional.ecommerceMall.customer.customers.checkout.create(
        customerConnection,
        {
          body: {} satisfies IEcommerceMallOrder.ICreate,
        },
      );
    },
  );
}

