    ...(props.body.maxPrice !== undefined && {
      base_price: { lte: props.body.maxPrice },
    }),
    ...(props.body.inStock && {
      variants: { some: { quantity: { gt: 0 } } },
    }),
  } satisfies Prisma.ecommerce_mall_productsWhereInput;
  const orderByInput = (
    props.body.sort === "price_asc"
      ? { base_price: "asc" as const }
