@Controller("/ecommerceMall/shipments/:shipmentId/items")
export class EcommercemallShipmentsItemsController {
  /**
   * Add order items to an existing shipment for shipping preparation.
   *
   * This endpoint allows sellers to include additional order items in a shipment before adding tracking information. All items within a shipment must belong to the same seller and have 'paid' status. Items can only belong to one shipment at a time.
   *
   * The seller can only update shipments they own. Items can only be added while the shipment is in 'created' state (before tracking information is added). Once tracking is added and shipment transitions to 'in transit', no further items can be added.
   *
   * If any validation fails during the operation, all changes are rolled back to maintain data consistency. The seller receives detailed error information specifying which validation failed.
   *
   * @param connection
   * @param shipmentId Unique identifier of the shipment to update (global scope)
   * @param body Order item identifiers to add to the shipment
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor null
   * @x-autobe-specification Implement the following steps for adding items to a shipment:
   *
   * 1. **Validation Phase**:
   *    - Verify shipment exists and is not soft-deleted (deleted_at IS NULL)
   *    - Verify shipment is in 'created' state (tracking_number is NULL or empty)
   *    - Verify authenticated seller owns the shipment (ecommerce_mall_seller_id matches)
   *    - Validate all orderItemIds exist and belong to the same order as the shipment
   *    - Verify all order items have status = 'paid'
   *    - Verify no order item is already assigned to another shipment (ecommerce_mall_shipment_items)
   *    - Verify all order items belong to the same seller as the shipment
   *
   * 2. **Transaction Phase**:
   *    - Create ecommerce_mall_shipment_items records for each order item
   *    - Update ecommerce_mall_order_items status to 'shipped' for all included items
   *    - Record the shipped timestamp synchronized across all items
   *
   * 3. **Rollback Handling**:
   *    - If any item fails validation or update, rollback all previously created shipment_items
   *    - Do not create partial shipments - either all items succeed or none do
   *    - Return specific error message indicating which items failed
   *
   * 4. **Authorization**:
   *    - Seller can only update their own shipments
   *    - Verify seller has active (non-suspended) account status
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async update(
    @TypedParam("shipmentId")
    shipmentId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IEcommerceMallShipment.IUpdate,
  ): Promise<IEcommerceMallShipment.ISummary> {
    try {
      return await patchEcommerceMallShipmentsShipmentIdItems({
        shipmentId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed information about a specific shipment item within a shipment.
   *
   * This endpoint returns the shipment item data along with its associated order item details including the product name, variant options, quantity, unit price, and product snapshot information captured at the time of purchase. The response provides complete context about what item was shipped.
   *
   * The shipment item links a physical shipment package to the specific order item it contains. This allows customers and sellers to verify shipment contents and track individual item fulfillment status within a shipment.
   *
   * @param connection
   * @param shipmentId Unique identifier of the shipment containing this item
   * @param shipmentItemId Unique identifier of the shipment item to retrieve
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor null
   * @x-autobe-specification Query the ecommerce_mall_shipment_items table filtering by id = shipmentItemId and ecommerce_mall_shipment_id = shipmentId.
   *
   * Join with ecommerce_mall_shipments to verify the shipment exists and is not soft-deleted (deleted_at IS NULL).
   *
   * Join with ecommerce_mall_order_items to retrieve the order item details (quantity, unit_price, status).
   *
   * Join with ecommerce_mall_product_snapshots to retrieve the product name, description, and images captured at purchase time.
   *
   * Join with ecommerce_mall_product_snapshot_variants to retrieve the variant SKU and option values.
   *
   * Authorization: The authenticated user must be either the seller who created the shipment (from ecommerce_mall_shipments.ecommerce_mall_seller_id) or the customer who placed the order (from ecommerce_mall_orders.ecommerce_mall_customer_id via the shipment's order).
   *
   * Return 404 if shipment item not found, shipment not found, or shipment is soft-deleted.
   *
   * Return 403 if user is neither the seller nor the customer.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":shipmentItemId")
  public async at(
    @TypedParam("shipmentId")
    shipmentId: string & tags.Format<"uuid">,
    @TypedParam("shipmentItemId")
    shipmentItemId: string & tags.Format<"uuid">,
  ): Promise<IEcommerceMallShipmentItem> {
    try {
